from pybricks.hubs import TechnicHub
from pybricks.iodevices import XboxController
from pybricks.parameters import Color, Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import Car

# Set up all devices.
Zeux = TechnicHub()
Drive = Motor(Port.D, Direction.COUNTERCLOCKWISE)
Steer = Motor(Port.A, Direction.CLOCKWISE)
Bucket = Motor(Port.C, Direction.CLOCKWISE)
Boom = Motor(Port.B, Direction.CLOCKWISE)
car = Car(Steer, Drive)
Xbox = XboxController()


# The main program starts here.
Zeux.light.on(Color.YELLOW)
while True:
    if Xbox.triggers()[1]:
        car.drive_power(Xbox.triggers()[1])
    else:
        car.drive_power(-1 * Xbox.triggers()[0])
    car.steer(0.5 * Xbox.joystick_left()[0])
    Boom.dc(Xbox.joystick_right()[1])
    Bucket.dc(Xbox.joystick_right()[0])
